package com.airbridge.engine

import java.io.File
import java.security.cert.CertificateException
import java.security.cert.CertificateFactory
import java.security.cert.X509Certificate

/** Fixtures are freshly generated by test-native-interop.ts, never committed keys. */
fun main(args: Array<String>) {
    fun chain(path: String) = File(path).inputStream().use { input ->
        CertificateFactory.getInstance("X.509").generateCertificates(input).map { it as X509Certificate }.toTypedArray()
    }
    val real = chain(args[0])
    val impostor = chain(args[1])
    val renewed = chain(args[2])
    var pin: ByteArray? = null
    var writes = 0
    val manager = PinnedTlsTrust({ pin }, { pin = it; writes++ })
    fun reject(block: () -> Unit) {
        try { block(); error("Untrusted TLS identity was accepted") }
        catch (_: CertificateException) {}
    }
    reject { manager.checkServerTrusted(arrayOf(real.first(), impostor.last()), "RSA") }
    check(pin == null) { "Failed first validation persisted a pin" }
    manager.checkServerTrusted(real, "RSA")
    check(pin!!.contentEquals(real.last().encoded) && writes == 1)
    manager.checkServerTrusted(real, "RSA")
    // A fresh instance must reload the saved pin, not silently replace it.
    val restored = PinnedTlsTrust({ pin }, { error("Saved TLS identity was overwritten") })
    reject { restored.checkServerTrusted(impostor, "RSA") }
    restored.checkServerTrusted(renewed, "RSA")
    check(!real.first().encoded.contentEquals(renewed.first().encoded))
    check(writes == 1)
    println("TLS TRUST: ALL PASS (first-use validation, persistent CA pin, impostor rejection, leaf renewal)")
}
